// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("splits an assignment into tokens with their kinds", () -> {
        eq(tokenize("x=1+y2"), List.of(new Token(Kind.IDENT, "x", 0), new Token(Kind.OP, "=", 1),
            new Token(Kind.NUMBER, "1", 2), new Token(Kind.OP, "+", 3), new Token(Kind.IDENT, "y2", 4)));
    });
    test("records each token's 0-based start, skipping all whitespace", () -> {
        eq(tokenize("  ab\t*\n(c_1 )"), List.of(new Token(Kind.IDENT, "ab", 2), new Token(Kind.OP, "*", 5),
            new Token(Kind.OP, "(", 7), new Token(Kind.IDENT, "c_1", 8), new Token(Kind.OP, ")", 12)));
        eq(tokenize(""), List.of());
        eq(tokenize(" \n "), List.of());
    });
    test("reads a decimal as one number and splits 12ab in two", () -> {
        eq(tokenize("3.14*r"), List.of(new Token(Kind.NUMBER, "3.14", 0), new Token(Kind.OP, "*", 4),
            new Token(Kind.IDENT, "r", 5)));
        eq(tokenize("12ab"), List.of(new Token(Kind.NUMBER, "12", 0), new Token(Kind.IDENT, "ab", 2)));
        eq(tokenize("_9-007"), List.of(new Token(Kind.IDENT, "_9", 0), new Token(Kind.OP, "-", 2),
            new Token(Kind.NUMBER, "007", 3)));
    });
    test("takes the longest operator", () -> {
        eq(tokenize("a<=b"), List.of(new Token(Kind.IDENT, "a", 0), new Token(Kind.OP, "<=", 1),
            new Token(Kind.IDENT, "b", 3)));
        eq(tokenize("a==b!=c>=d").stream().map(Token::text).toList(),
            List.of("a", "==", "b", "!=", "c", ">=", "d"));
        eq(tokenize("a=<b>/=").stream().map(Token::text).toList(), List.of("a", "=", "<", "b", ">", "/", "="));
    });
    test("an unexpected character is reported with its offset", () -> {
        raises(IllegalArgumentException.class, () -> tokenize("a + $b"), "unexpected '$' at 4");
        raises(IllegalArgumentException.class, () -> tokenize("!x"), "unexpected '!' at 0");
        raises(IllegalArgumentException.class, () -> tokenize("ok;"), "unexpected ';' at 2");
    });
    test("a dot must be followed by a digit", () -> {
        raises(IllegalArgumentException.class, () -> tokenize("3."), "unexpected '.' at 1");
        raises(IllegalArgumentException.class, () -> tokenize("x 3.y"), "unexpected '.' at 3");
        raises(IllegalArgumentException.class, () -> tokenize(".5"), "unexpected '.' at 0");
    });
    test("a number has at most one decimal point", () -> {
        eq(tokenize("1.5").size(), 1);
        raises(IllegalArgumentException.class, () -> tokenize("1.2.3"), "unexpected '.' at 3");
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("splits a line on commas and keeps spaces", () -> {
        eq(parse("a,b,c"), List.of(List.of("a", "b", "c")));
        eq(parse(" a , b"), List.of(List.of(" a ", " b")));
    });
    test("keeps empty fields, including a trailing one", () -> {
        eq(parse("a,,b,"), List.of(List.of("a", "", "b", "")));
        eq(parse(","), List.of(List.of("", "")));
    });
    test("a quoted field keeps commas, spaces and newlines", () -> {
        eq(parse("7,\"Smith, J\""), List.of(List.of("7", "Smith, J")));
        eq(parse("\"two\nlines\",\" x \"\nnext"), List.of(List.of("two\nlines", " x "), List.of("next")));
        eq(parse("\"\",\"\""), List.of(List.of("", "")));
    });
    test("a doubled quote inside quotes is one quote", () -> {
        eq(parse("\"say \"\"hi\"\"\",x"), List.of(List.of("say \"hi\"", "x")));
        eq(parse("\"\"\"\""), List.of(List.of("\"")));
    });
    test("records end at LF or CRLF, and a final line end adds none", () -> {
        eq(parse("a,b\r\nc\n"), List.of(List.of("a", "b"), List.of("c")));
        eq(parse("x\n\ny"), List.of(List.of("x"), List.of(""), List.of("y")));
        eq(parse("\"q\"\r\n"), List.of(List.of("q")));
        eq(parse(""), List.of());
        eq(parse("\n"), List.of(List.of("")));
        eq(parse("a\rb,c"), List.of(List.of("a\rb", "c")));
    });
    test("an unterminated quote is reported at its opening offset", () -> {
        raises(IllegalArgumentException.class, () -> parse("a,\"bc"), "unterminated quote at 2");
        raises(IllegalArgumentException.class, () -> parse("x\n\"a\"\""), "unterminated quote at 2");
    });
    test("text after a closing quote is an error at that offset", () -> {
        raises(IllegalArgumentException.class, () -> parse("\"ab\"c,d"), "unexpected 'c' at 4");
        raises(IllegalArgumentException.class, () -> parse("x,\"a\" ,b"), "unexpected ' ' at 5");
    });
    test("a quote inside an unquoted field is an error", () -> {
        raises(IllegalArgumentException.class, () -> parse("ab\"c"), "unexpected '\"' at 2");
        raises(IllegalArgumentException.class, () -> parse("ok\n5\""), "unexpected '\"' at 4");
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    var schema = Map.of("port", Type.INT, "debug", Type.BOOL, "name", Type.STRING, "url", Type.STRING);
    test("loads typed values", () -> {
        var c = load(List.of("port=8080", "debug=true", "name=api"), schema, Set.of());
        eq(c.values(), Map.of("port", 8080, "debug", true, "name", "api"));
        eq(c.errors(), List.of());
        ok(c.values().get("port") instanceof Integer, "port is an Integer");
    });
    test("skips blanks and comments and trims key and value", () -> {
        var c = load(List.of("  # the port", "", "   ", "  port =  -80  ", "debug= false"), schema, Set.of());
        eq(c.values(), Map.of("port", -80, "debug", false));
        eq(c.errors(), List.of());
    });
    test("splits at the first = and unwraps one pair of quotes", () -> {
        var c = load(List.of("url=http://h/?a=b", "name=\"  x # y \""), schema, Set.of());
        eq(c.values(), Map.of("url", "http://h/?a=b", "name", "  x # y "));
        eq(load(List.of("name=", "url=a # b"), schema, Set.of()).values(), Map.of("name", "", "url", "a # b"));
        eq(load(List.of("name=\"\"x\"\"", "url=\"half"), schema, Set.of()).values(),
            Map.of("name", "\"x\"", "url", "\"half"));
    });
    test("a line without a key and an = is reported with its number", () -> {
        eq(load(List.of("# c", "just text", "=5", " = "), schema, Set.of()).errors(), List.of(
            "line 2: expected key=value", "line 3: expected key=value", "line 4: expected key=value"));
    });
    test("reports unknown keys and badly typed values", () -> {
        var c = load(List.of("prot=80", "port=80x", "debug=True", "port=99999999999"), schema, Set.of());
        eq(c.errors(), List.of("line 1: unknown key 'prot'", "line 2: 'port' must be an integer, got '80x'",
            "line 3: 'debug' must be true or false, got 'True'",
            "line 4: duplicate key 'port' (first on line 2)"));
        eq(c.values(), Map.of());
    });
    test("a duplicate names the line where the key first appeared", () -> {
        var c = load(List.of("name=a", "", "port=1", "name=b", "name=c"), schema, Set.of());
        eq(c.errors(), List.of("line 4: duplicate key 'name' (first on line 1)",
            "line 5: duplicate key 'name' (first on line 1)"));
        eq(c.values(), Map.of("name", "a", "port", 1));
    });
    test("lists missing required keys after the line errors, sorted", () -> {
        var c = load(List.of("debug=maybe"), schema, Set.of("url", "port", "debug"));
        eq(c.errors(), List.of("line 1: 'debug' must be true or false, got 'maybe'",
            "missing required key 'port'", "missing required key 'url'"));
        eq(load(List.of(), schema, Set.of("name")).errors(), List.of("missing required key 'name'"));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("returns each complete line without its line end", () -> {
        var d = new LineDecoder(100);
        eq(d.feed("hello\nworld\n"), List.of("hello", "world"));
        eq(d.buffered(), 0);
    });
    test("buffers a partial line until its newline arrives", () -> {
        var d = new LineDecoder(100);
        eq(d.feed("hel"), List.of());
        eq(d.buffered(), 3);
        eq(d.feed("lo\nwo"), List.of("hello"));
        eq(d.buffered(), 2);
        eq(d.feed("rld\n"), List.of("world"));
    });
    test("drops the CR of a CRLF even when it is split across chunks", () -> {
        var d = new LineDecoder(100);
        eq(d.feed("a\r"), List.of());
        eq(d.feed("\nb\r\n"), List.of("a", "b"));
        eq(d.feed("x\ry\r"), List.of());
        eq(d.feed("\r\n"), List.of("x\ry\r"));
    });
    test("an empty line is an empty frame", () -> {
        eq(new LineDecoder(10).feed("\n\r\n\n"), List.of("", "", ""));
    });
    test("a frame of exactly maxLength is kept, with or without CR", () -> {
        var d = new LineDecoder(3);
        eq(d.feed("abc\nxyz\r"), List.of("abc"));
        eq(d.feed("\n"), List.of("xyz"));
        eq(d.dropped(), 0);
    });
    test("an over-long frame is dropped up to its newline and counted once", () -> {
        var d = new LineDecoder(3);
        eq(d.feed("abcd"), List.of());
        eq(d.buffered(), 0);
        eq(d.feed("efgh"), List.of());
        eq(d.feed("ij\nok\nabc\r\r\nz\n"), List.of("ok", "z"));
        eq(d.dropped(), 2);
    });
    test("never holds more than maxLength + 1 chars", () -> {
        var d = new LineDecoder(5);
        for (int i = 0; i < 200; i++) {
            d.feed("xxxxxxx");
            ok(d.buffered() <= 6, "buffered " + d.buffered());
        }
        eq(d.feed("\nhi\n"), List.of("hi"));
        eq(d.dropped(), 1);
    });
    test("encode appends a newline and refuses embedded line breaks", () -> {
        eq(encode("PING"), "PING\n");
        eq(encode(""), "\n");
        raises(IllegalArgumentException.class, () -> encode("a\nb"));
        raises(IllegalArgumentException.class, () -> encode("a\r"));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("writes the scalars", () -> {
        eq(toJson(null), "null");
        eq(toJson(true), "true");
        eq(toJson(42), "42");
        eq(toJson(-7_000_000_000L), "-7000000000");
        eq(toJson("hi"), "\"hi\"");
    });
    test("escapes quotes, backslashes, newlines, CRs and tabs", () -> {
        eq(toJson("say \"hi\""), "\"say \\\"hi\\\"\"");
        eq(toJson("C:\\tmp"), "\"C:\\\\tmp\"");
        eq(toJson("a\nb\rc\td"), "\"a\\nb\\rc\\td\"");
    });
    test("writes other control chars as 4-hex-digit escapes and keeps the rest", () -> {
        eq(toJson("\u0001x\u001f"), "\"\\u0001x\\u001f\"");
        eq(toJson("\b\f\u007f"), "\"\\u0008\\u000c\u007f\"");
        eq(toJson("caf\u00e9 \u20ac /"), "\"caf\u00e9 \u20ac /\"");
    });
    test("writes lists, nested and empty, with no spaces", () -> {
        eq(toJson(List.of(1, List.of(), "a", List.of(false))), "[1,[],\"a\",[false]]");
        eq(toJson(Arrays.asList(1, null)), "[1,null]");
    });
    test("writes maps in their own iteration order", () -> {
        var m = new LinkedHashMap<String, Object>();
        m.put("b", 1);
        m.put("a", Map.of());
        m.put("c", null);
        eq(toJson(m), "{\"b\":1,\"a\":{},\"c\":null}");
        eq(toJson(new TreeMap<>(Map.of("y", "2", "x", List.of()))), "{\"x\":[],\"y\":\"2\"}");
    });
    test("escapes map keys like any string", () -> {
        eq(toJson(Map.of("a\"b", 1)), "{\"a\\\"b\":1}");
    });
    test("refuses unsupported types at any depth, naming the type", () -> {
        raises(IllegalArgumentException.class, () -> toJson(1.5), "unsupported type: Double");
        raises(IllegalArgumentException.class, () -> toJson(List.of(1, (short) 2)), "unsupported type: Short");
        raises(IllegalArgumentException.class, () -> toJson(Map.of("k", List.of(new Object()))), "unsupported type: Object");
        raises(IllegalArgumentException.class, () -> toJson(Map.of(1, 2)), "unsupported type: Integer");
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("reads the scalars", () -> {
        eq(parse("null"), null);
        eq(parse(" true"), true);
        eq(parse("false \n"), false);
        ok(parse("42") instanceof Long, "a number is a Long");
        eq(parse("-7"), -7L);
        eq(parse("\"hi\""), "hi");
    });
    test("reads nested arrays and objects, keeping key order", () -> {
        var v = parse("{ \"z\" : [1, 2, {\"b\":null}],\r\n\t\"a\":\"x\", \"e\": {}, \"l\": [] }");
        eq(v, Map.of("z", List.of(1, 2, Collections.singletonMap("b", null)), "a", "x", "e", Map.of(), "l", List.of()));
        eq(new ArrayList<>(((Map<?, ?>) v).keySet()), List.of("z", "a", "e", "l"));
    });
    test("decodes every escape", () -> {
        eq(parse("\"a\\\"b\\\\c\\/d\\n\\r\\t\\u00e9\\u20AC\""), "a\"b\\c/d\n\r\t\u00e9\u20ac");
    });
    test("numbers: no leading zeros, no fractions, and within long", () -> {
        eq(parse("0"), 0L);
        eq(parse("-9223372036854775808"), Long.MIN_VALUE);
        raises(IllegalArgumentException.class, () -> parse("01"), "unexpected '1' at 1");
        raises(IllegalArgumentException.class, () -> parse("[1.5]"), "unexpected '.' at 2");
        raises(IllegalArgumentException.class, () -> parse(" 9223372036854775808"), "number out of range at 1");
        raises(IllegalArgumentException.class, () -> parse("-a"), "unexpected 'a' at 1");
        raises(IllegalArgumentException.class, () -> parse("+1"), "unexpected '+' at 0");
    });
    test("an unexpected char is reported at its offset", () -> {
        raises(IllegalArgumentException.class, () -> parse("[1 2]"), "unexpected '2' at 3");
        raises(IllegalArgumentException.class, () -> parse("{\"a\" 1}"), "unexpected '1' at 5");
        raises(IllegalArgumentException.class, () -> parse("[1,]"), "unexpected ']' at 3");
        raises(IllegalArgumentException.class, () -> parse("{1:2}"), "unexpected '1' at 1");
        raises(IllegalArgumentException.class, () -> parse("[trux]"), "unexpected 'x' at 4");
    });
    test("running out of text is reported at its end", () -> {
        raises(IllegalArgumentException.class, () -> parse(""), "unexpected end at 0");
        raises(IllegalArgumentException.class, () -> parse("[1,"), "unexpected end at 3");
        raises(IllegalArgumentException.class, () -> parse("\"abc"), "unexpected end at 4");
        raises(IllegalArgumentException.class, () -> parse("{\"a\":1"), "unexpected end at 6");
        raises(IllegalArgumentException.class, () -> parse("-"), "unexpected end at 1");
        raises(IllegalArgumentException.class, () -> parse("nul"), "unexpected end at 3");
    });
    test("refuses trailing text, raw control chars and bad escapes", () -> {
        raises(IllegalArgumentException.class, () -> parse("1 x"), "unexpected 'x' at 2");
        raises(IllegalArgumentException.class, () -> parse("{} {}"), "unexpected '{' at 3");
        raises(IllegalArgumentException.class, () -> parse("\"a\tb\""), "at 2");
        raises(IllegalArgumentException.class, () -> parse("\"\\q\""), "unexpected 'q' at 2");
        raises(IllegalArgumentException.class, () -> parse("\"\\u12G4\""), "unexpected 'G' at 5");
    });
    test("refuses a repeated key, pointing at its opening quote", () -> {
        raises(IllegalArgumentException.class, () -> parse("{\"a\":1,\"a\":2}"), "duplicate key \"a\" at 7");
        eq(parse("{\"a\":{\"a\":1}}"), Map.of("a", Map.of("a", 1)));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("decodes the current version", () -> {
        eq(decode("3;Ada;Lovelace;ada@x;Y"), new User("Ada", "Lovelace", "ada@x", true));
        eq(decode("3;Alan;Turing;at@x;N"), new User("Alan", "Turing", "at@x", false));
    });
    test("migrates v1: opt-in defaults to N and the name is split", () -> {
        eq(decode("1;Ada Lovelace;ada@x"), new User("Ada", "Lovelace", "ada@x", false));
    });
    test("migrates v2, splitting the name at the first space only", () -> {
        eq(decode("2;Grace Brewster Hopper;g@x;Y"), new User("Grace", "Brewster Hopper", "g@x", true));
        eq(decode("2; Lead;l@x;N"), new User("", "Lead", "l@x", false));
    });
    test("keeps empty fields, trailing ones included", () -> {
        eq(decode("2;Cher;c@x;N"), new User("Cher", "", "c@x", false));
        eq(decode("1;Prince;"), new User("Prince", "", "", false));
        eq(decode("3;;;;Y"), new User("", "", "", true));
    });
    test("encode writes the latest version and upgrade rewrites old lines", () -> {
        eq(encode(new User("Ada", "Lovelace", "ada@x", true)), "3;Ada;Lovelace;ada@x;Y");
        eq(upgrade("1;Ada Lovelace;ada@x"), "3;Ada;Lovelace;ada@x;N");
        eq(upgrade("2;Cher;c@x;Y"), "3;Cher;;c@x;Y");
        eq(upgrade("3;A;B;c;N"), "3;A;B;c;N");
    });
    test("decode(encode(u)) gives u back", () -> {
        for (var u : List.of(new User("Ada", "Lovelace", "a@x", true), new User("", "", "", false),
                new User("Mary Ann", "Evans", "e@x", true), new User("x", "", "", true))) {
            eq(decode(encode(u)), u);
        }
    });
    test("refuses unknown versions and wrong field counts", () -> {
        raises(IllegalArgumentException.class, () -> decode("9;a;b"), "unknown version '9'");
        raises(IllegalArgumentException.class, () -> decode("Ada;x"), "unknown version 'Ada'");
        raises(IllegalArgumentException.class, () -> decode("2;Ada;a@x"), "version 2 expects 4 fields, got 3");
        raises(IllegalArgumentException.class, () -> decode("1;A;b;"), "version 1 expects 3 fields, got 4");
        raises(IllegalArgumentException.class, () -> decode("3;A;B;c;N;"), "version 3 expects 5 fields, got 6");
    });
    test("refuses a bad opt-in, and encode refuses separators in fields", () -> {
        raises(IllegalArgumentException.class, () -> decode("2;Ada;a@x;yes"), "bad opt-in 'yes'");
        raises(IllegalArgumentException.class, () -> decode("3;A;B;c;"), "bad opt-in ''");
        raises(IllegalArgumentException.class, () -> encode(new User("A;B", "C", "d", true)));
        raises(IllegalArgumentException.class, () -> encode(new User("A", "C", "d\ne", true)));
        raises(IllegalArgumentException.class, () -> encode(new User("A", "C\r", "d", true)));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("encode escapes and terminates every item", () -> {
        eq(encode(List.of("a", "b;c", "d\\")), "a;b\\;c;d\\\\;");
        eq(encode(List.of()), "");
        eq(encode(List.of("")), ";");
        eq(encode(List.of("", "")), ";;");
    });
    test("decode inverts encode, telling [] and [\"\"] apart", () -> {
        eq(decode("a;b\\;c;d\\\\;"), List.of("a", "b;c", "d\\"));
        eq(decode(""), List.of());
        eq(decode(";"), List.of(""));
        eq(decode("\\\\\\;;"), List.of("\\;"));
    });
    test("decode reports malformed text with its offset", () -> {
        raises(IllegalArgumentException.class, () -> decode("a\\"), "dangling escape at 1");
        raises(IllegalArgumentException.class, () -> decode("a\\x;"), "bad escape at 1");
        raises(IllegalArgumentException.class, () -> decode("a;bc"), "unterminated item at 2");
        raises(IllegalArgumentException.class, () -> decode("x;\\;"), "unterminated item at 2");
    });
    test("the codec survives 2000 random lists", () -> {
        var rnd = new Random(42);
        for (int t = 0; t < 2000; t++) {
            var x = new ArrayList<String>();
            for (int i = rnd.nextInt(6); i > 0; i--) {
                var sb = new StringBuilder();
                for (int j = rnd.nextInt(5); j > 0; j--) sb.append("ab;\\ ".charAt(rnd.nextInt(5)));
                x.add(sb.toString());
            }
            eq(decode(encode(x)), x);
        }
    });
    test("finds nothing for a correct codec", () -> {
        var store = new ArrayList<List<String>>();
        Function<List<String>, String> enc = x -> {
            store.add(List.copyOf(x));
            return String.valueOf(store.size() - 1);
        };
        eq(findCounterexample(enc, s -> store.get(Integer.parseInt(s)), 7, 300), Optional.empty());
        ok(store.size() >= 300, "it ran every trial");
    });
    test("shrinks a join-with-; failure to the empty list", () -> {
        eq(findCounterexample(x -> String.join(";", x), s -> List.of(s.split(";", -1)), 1, 200),
            Optional.of(List.of()));
    });
    test("shrinks an unescaped codec's failure to [;]", () -> {
        Function<List<String>, String> enc = x -> x.stream().map(s -> s + ";").collect(Collectors.joining());
        Function<String, List<String>> dec = s -> s.isEmpty() ? List.of() : List.of(s.substring(0, s.length() - 1).split(";", -1));
        eq(findCounterexample(enc, dec, 3, 200), Optional.of(List.of(";")));
        eq(findCounterexample(enc, dec, 99, 200), Optional.of(List.of(";")));
    });
    test("a throwing codec fails too; shrinks chars as well as items; obeys trials", () -> {
        var store = new ArrayList<List<String>>();
        Function<List<String>, String> enc = x -> {
            store.add(List.copyOf(x));
            return String.valueOf(store.size() - 1);
        };
        Function<String, List<String>> dec = s -> {
            var x = store.get(Integer.parseInt(s));
            if (x.size() == 4) throw new IllegalStateException("boom");
            return x;
        };
        eq(findCounterexample(enc, dec, 5, 200), Optional.of(List.of("", "", "", "")));
        store.clear();
        eq(findCounterexample(enc, dec, 5, 0), Optional.empty());
        eq(store.size(), 0);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

